"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["60850"],{2411(e){e.exports=JSON.parse('{"id":"FIN-764","slug":"producer-price-index","term":"Producer Price Index (PPI)","also_known_as":["PPI"],"difficulty":"Intermediate","definition":"The Producer Price Index (PPI) measures the average change over time in the prices that domestic producers receive for their goods and services, reflecting price changes at the wholesale or factory level.","explanation":["While the Consumer Price Index tracks prices paid by households, the PPI tracks prices at earlier stages of production, such as raw materials, intermediate goods used in manufacturing and finished goods sold by producers.","For example, if the prices of steel, chemicals and manufactured goods sold by factories rise, the PPI will increase, even before consumers see higher prices in shops.","The PPI is watched closely as a possible early signal of consumer inflation. When producers face higher costs, they often pass at least some of those increases on to consumers, so a rising PPI can suggest that consumer prices may rise later. However, the link is not exact, since businesses may absorb some cost increases by accepting lower profit margins.","Different countries publish their own producer price measures, sometimes called output and input price indices. Businesses also use the PPI to adjust long-term contracts for changes in costs."],"note":"","total":1500,"prev":{"slug":"procurement","term":"Procurement"},"next":{"slug":"producer-surplus","term":"Producer Surplus"}}')}}]);